"use client";

import { useId, useRef, type ReactElement, type ReactNode } from "react";

import { IconClose } from "@rhs-ui/icons";
import { DEFAULT_LABELS, type EventDetailsLabels, type EventInfo, type EventMoment } from "@rhs-ui/application/event-details-popover/event";
import { EventDetailsPanel } from "@rhs-ui/application/event-details-popover/panel";
import { Popover, PopoverClose, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { cn } from "@/lib/utils";

export type { EventDetailsLabels, EventInfo, EventMoment, EventPerson, EventStatus } from "@rhs-ui/application/event-details-popover/event";
export { EventDetailsPanel, type EventDetailsPanelProps } from "@rhs-ui/application/event-details-popover/panel";

export interface EventDetailsPopoverProps {
  /** The event: title, start, end, time zone, place, link, people, description and status. */
  event: EventInfo;
  /** The reader's own IANA time zone. When it shows a different clock than the event's zone, the panel writes both. Default "UTC". */
  viewerTimeZone?: string;
  /** The language of the dates, times and names of zones. Default "en-US". */
  locale?: string;
  /** The buttons at the foot of the panel: Join, Edit, Cancel. Put them on `Button`s; a button that closes the popover goes in a `PopoverClose`. */
  actions?: ReactNode;
  /** The event chip, or any one element that is a button: it opens the panel and gets the focus back when it closes. */
  children: ReactElement;
  /** What "now" is, for "Happening now" and "Ended 3 days ago". Pass it for output that does not change between server and browser. Default: the current time. */
  now?: EventMoment;
  /** Whether the popover is open, when you control it. */
  open?: boolean;
  /** Whether it is open to begin with. */
  defaultOpen?: boolean;
  /** Called when it opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** The side of the chip the panel opens on. It moves to another side when there is no room. Default "bottom". */
  side?: "top" | "right" | "bottom" | "left";
  /** How the panel lines up with the chip along that side. Default "start". */
  align?: "start" | "center" | "end";
  /** The words the panel says, for translation. */
  labels?: EventDetailsLabels;
  /** Classes for the panel, for a different width. */
  className?: string;
}

/**
 * Click an event on a calendar or a schedule and read it without leaving the page: the title with its status in
 * words, the day and the time, the reader's own time when their zone differs, the place or a link to join, who is
 * invited and a description cut to four lines, with your actions at the foot. A cancelled event has its title struck
 * through and says Cancelled; an event that is over says how long ago. The panel is anchored to the chip you pass as
 * `children`, does not trap focus or dim the page, closes on Escape or a click outside, and gives the focus back to the
 * chip. It never leaves the screen: on a phone it takes the width that is there.
 */
export function EventDetailsPopover({
  event,
  viewerTimeZone,
  locale,
  actions,
  children,
  now,
  open,
  defaultOpen,
  onOpenChange,
  side = "bottom",
  align = "start",
  labels,
  className,
}: EventDetailsPopoverProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const titleId = useId();
  const panel = useRef<HTMLDivElement>(null);

  return (
    <Popover open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
      <PopoverTrigger asChild>{children}</PopoverTrigger>
      <PopoverContent
        ref={panel}
        data-slot="event-details-popover"
        side={side}
        align={align}
        sideOffset={8}
        collisionPadding={12}
        tabIndex={-1}
        aria-labelledby={titleId}
        // Focus starts on the panel itself, so a screen reader reads its name and the first Tab lands on the first action; not on the close button.
        onOpenAutoFocus={(focus) => {
          focus.preventDefault();
          panel.current?.focus({ preventScroll: true });
        }}
        // The panel is never taller than the room there is: on a small screen it scrolls inside itself instead of running off the edge, and the close button stays in view.
        className={cn(
          "relative w-84 max-w-[min(21rem,var(--radix-popover-content-available-width))] max-h-(--radix-popover-content-available-height) scroll-pt-12 overflow-x-hidden overflow-y-auto overscroll-contain p-0 [scrollbar-color:color-mix(in_oklab,var(--foreground)_28%,transparent)_transparent] [scrollbar-width:thin]",
          className,
        )}
      >
        <EventDetailsPanel
          event={event}
          viewerTimeZone={viewerTimeZone}
          locale={locale}
          actions={actions}
          now={now}
          labels={labels}
          titleId={titleId}
          close={
            <PopoverClose asChild>
              <button
                type="button"
                aria-label={words.close}
                className="inline-flex size-8 shrink-0 items-center justify-center rounded-md bg-popover text-muted-foreground outline-none transition-colors duration-150 hover:bg-muted hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 motion-reduce:transition-none pointer-coarse:size-10"
              >
                <IconClose size={16} />
              </button>
            </PopoverClose>
          }
        />
      </PopoverContent>
    </Popover>
  );
}

"use client";

import { useEffect, useId, useRef, useState, type ComponentProps, type ReactNode } from "react";

import { IconBan, IconClock, IconExternal, IconPin, IconUsers, IconVideo } from "@rhs-ui/icons";
import {
  DEFAULT_LABELS,
  agoText,
  fill,
  momentOf,
  numberText,
  peopleLine,
  phaseOf,
  safeLink,
  viewerLine,
  whenOf,
  zoneText,
  type EventDetailsLabels,
  type EventInfo,
  type EventMoment,
} from "@rhs-ui/application/event-details-popover/event";
import { Avatar, AvatarFallback, AvatarGroup, AvatarGroupCount, AvatarImage, initialsOf } from "@rhs-ui/primitives/avatar";
import { Badge } from "@rhs-ui/primitives/badge";
import { cn } from "@/lib/utils";

export interface EventDetailsPanelProps extends Omit<ComponentProps<"div">, "title" | "children"> {
  /** The event: title, start, end, time zone, place, link, people, description and status. */
  event: EventInfo;
  /** The reader's own IANA time zone. When it shows a different clock than the event's zone, the panel writes both. Default "UTC". */
  viewerTimeZone?: string;
  /** The language of the dates, times and names of zones. Default "en-US". */
  locale?: string;
  /** The buttons at the foot: Join, Edit, Cancel. Put them on `Button`s; the panel lays them out in a row that wraps. */
  actions?: ReactNode;
  /** What "now" is, for "Happening now" and "Ended 3 days ago". Pass it for output that does not change between server and browser. Default: the current time. */
  now?: EventMoment;
  /** The words the panel says, for translation. */
  labels?: EventDetailsLabels;
  /** The element that closes the panel, drawn at the top end of the title. The popover puts its close button here. */
  close?: ReactNode;
  /** The id of the title, so a dialog can be named by it. */
  titleId?: string;
}

/** The failure text, darkened toward the foreground so small red words reach 4.5:1 on the panel. */
const DANGER_TEXT = "text-[color:color-mix(in_oklch,var(--destructive),var(--foreground)_30%)]";

function Row({ icon, children }: { icon: ReactNode; children: ReactNode }) {
  return (
    <li className="grid grid-cols-[1rem_minmax(0,1fr)] items-start gap-x-3">
      <span aria-hidden="true" className="mt-0.5 text-muted-foreground [&_svg]:size-4">
        {icon}
      </span>
      <div className="min-w-0">{children}</div>
    </li>
  );
}

/** Four lines of the description, and a button to read the rest, shown only when four lines really hide something. */
function Description({ text, more, less }: { text: string; more: string; less: string }) {
  const body = useRef<HTMLParagraphElement>(null);
  const [expanded, setExpanded] = useState(false);
  const [cut, setCut] = useState(false);
  const id = useId();

  useEffect(() => {
    const element = body.current;
    if (!element || expanded) return;
    const measure = () => setCut(element.scrollHeight > element.clientHeight + 1);
    measure();
    if (typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, [text, expanded]);

  return (
    <div className="border-t border-border px-4 py-3">
      <p
        id={id}
        ref={body}
        className={cn("text-sm leading-relaxed text-pretty whitespace-pre-line text-muted-foreground [overflow-wrap:anywhere]", !expanded && "line-clamp-4")}
      >
        {text}
      </p>
      {cut || expanded ? (
        <button
          type="button"
          aria-expanded={expanded}
          aria-controls={id}
          onClick={() => setExpanded((value) => !value)}
          className="mt-1.5 -ml-1 rounded-sm px-1 text-xs font-medium text-foreground underline-offset-4 outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/40"
        >
          {expanded ? less : more}
        </button>
      ) : null}
    </div>
  );
}

/**
 * Everything about one event, as the content of a card: the title with its status in words, the day and the time, the
 * time in the reader's own zone when it differs, the place or the link to join, who is invited, a description cut to
 * four lines and the actions. It is what EventDetailsPopover shows, usable by itself in a side panel, a sheet on a
 * phone or a page of its own.
 */
export function EventDetailsPanel({ event, viewerTimeZone = "UTC", locale = "en-US", actions, now, labels, close, titleId, className, ...props }: EventDetailsPanelProps) {
  const words: Required<EventDetailsLabels> = { ...DEFAULT_LABELS, ...labels };
  const ownTitleId = useId();
  const zone = event.timeZone ?? "UTC";
  const startAt = momentOf(event.start);
  const endAt = momentOf(event.end);
  const nowAt = momentOf(now) ?? Date.now();
  const cancelled = event.status === "cancelled";
  const phase = startAt === null ? "upcoming" : phaseOf(startAt, endAt, nowAt);

  const own = startAt === null ? null : whenOf(startAt, endAt, event.allDay === true, zone, locale, words);
  const theirs = startAt !== null && !event.allDay && viewerTimeZone !== zone ? whenOf(startAt, endAt, false, viewerTimeZone, locale, words) : null;
  // The reader's line appears only when their clock reads differently: two zones with the same offset say nothing new.
  const viewer = own && theirs ? viewerLine(own, theirs) : null;

  const link = event.link ? safeLink(event.link) : null;
  const people = event.attendees ?? [];
  const names = people.map((person) => person.name);
  const faces = people.slice(0, 4);
  const more = people.length - faces.length;

  return (
    <div
      data-slot="event-details-panel"
      data-status={event.status ?? "confirmed"}
      data-phase={phase}
      className={cn("relative flex min-w-0 flex-col text-sm text-popover-foreground", className)}
      {...props}
    >
      <div className={cn("px-4 pt-4", close ? "pr-12" : undefined)}>
        <div className="min-w-0">
          <h3
            id={titleId ?? ownTitleId}
            className={cn(
              "text-[0.9375rem] leading-snug font-semibold tracking-[-0.01em] text-pretty [overflow-wrap:anywhere]",
              cancelled && "text-muted-foreground line-through decoration-muted-foreground/70 decoration-[1.5px]",
            )}
          >
            {cancelled ? <span className="sr-only">{words.cancelled}: </span> : null}
            {event.title}
          </h3>
          {cancelled || event.status === "tentative" || phase !== "upcoming" ? (
            <div className="mt-2 flex flex-wrap items-center gap-1.5">
              {cancelled ? (
                <Badge variant="destructive" aria-hidden="true" className={DANGER_TEXT}>
                  <IconBan />
                  {words.cancelled}
                </Badge>
              ) : null}
              {!cancelled && event.status === "tentative" ? <Badge variant="outline">{words.tentative}</Badge> : null}
              {!cancelled && phase === "live" ? (
                <Badge>
                  <span aria-hidden="true" className="size-1.5 rounded-full bg-primary-foreground" />
                  {words.now}
                </Badge>
              ) : null}
              {!cancelled && phase === "past" && startAt !== null ? <Badge variant="muted">{fill(words.ended, { when: agoText(nowAt, endAt ?? startAt, locale) })}</Badge> : null}
            </div>
          ) : null}
        </div>
      </div>

      <ul className="grid gap-3.5 px-4 pt-3.5 pb-4">
        {own && startAt !== null ? (
          <Row icon={<IconClock />}>
            <p className="font-medium text-balance">{own.day}</p>
            <p className="mt-0.5 flex flex-wrap items-baseline gap-x-2 tabular-nums">
              <span>{own.time}</span>
              {viewer ? <span className="text-xs text-muted-foreground">{zoneText(startAt, zone, locale)}</span> : null}
            </p>
            {viewer ? (
              <p className="mt-1 flex flex-wrap items-baseline gap-x-2 tabular-nums">
                <span>{viewer}</span>
                <span className="text-xs text-muted-foreground">
                  {words.yourTime}, {zoneText(startAt, viewerTimeZone, locale)}
                </span>
              </p>
            ) : null}
          </Row>
        ) : null}

        {event.location ? (
          <Row icon={<IconPin />}>
            <p className="text-pretty [overflow-wrap:anywhere]">{event.location}</p>
          </Row>
        ) : null}

        {event.link ? (
          <Row icon={<IconVideo />}>
            {link ? (
              <>
                <a
                  href={link.href}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="group/link inline-flex items-center gap-1.5 rounded-sm font-medium text-foreground underline-offset-4 outline-none hover:underline focus-visible:ring-[3px] focus-visible:ring-ring/40"
                >
                  {words.join}
                  <IconExternal aria-hidden="true" className="size-3.5 shrink-0 text-muted-foreground" />
                  <span className="sr-only">{words.newTab}</span>
                </a>
                <p className="mt-0.5 truncate text-xs text-muted-foreground">{link.text}</p>
              </>
            ) : (
              <p className="text-pretty [overflow-wrap:anywhere]">{event.link}</p>
            )}
          </Row>
        ) : null}

        {people.length ? (
          <Row icon={<IconUsers />}>
            <div className="flex items-center gap-2.5">
              <AvatarGroup aria-hidden="true" className="-space-x-1 *:data-[slot=avatar]:ring-popover">
                {faces.map((person) => (
                  <Avatar key={person.id} size="sm">
                    {person.image ? <AvatarImage src={person.image} alt="" /> : null}
                    <AvatarFallback>{initialsOf(person.name)}</AvatarFallback>
                  </Avatar>
                ))}
                {more > 0 ? <AvatarGroupCount className="size-7 text-xs ring-popover">+{numberText(more, locale)}</AvatarGroupCount> : null}
              </AvatarGroup>
              <p className="font-medium tabular-nums">{fill(people.length === 1 ? words.attendeesOne : words.attendeesOther, { count: numberText(people.length, locale) })}</p>
            </div>
            <p className="mt-1.5 text-[0.8125rem] leading-snug text-pretty text-muted-foreground">{peopleLine(names, locale, words.andMore)}</p>
            {people.length > 3 ? (
              <ul aria-label={words.attendees} className="sr-only">
                {people.map((person) => (
                  <li key={person.id}>{person.name}</li>
                ))}
              </ul>
            ) : null}
          </Row>
        ) : null}
      </ul>

      {event.description ? <Description text={event.description} more={words.showMore} less={words.showLess} /> : null}

      {actions ? <div className="flex flex-wrap items-center gap-2 border-t border-border bg-muted/40 px-4 py-3">{actions}</div> : null}
      {/* Last in the DOM, like the close button of a Dialog: the first Tab lands on the first action. Drawn first, in a frame with no height that sticks to the top of whatever scrolls, so a panel taller than the screen keeps its way out in view. */}
      {close ? (
        <div className="sticky top-0 z-10 order-first h-0">
          {/* The bigger button of a touch screen keeps the centre of the small one, so it never reaches down over what is under the title. */}
          <div className="absolute top-2.5 right-2.5 pointer-coarse:top-1.5 pointer-coarse:right-1.5">{close}</div>
        </div>
      ) : null}
    </div>
  );
}

/**
 * The facts and the words behind EventDetailsPopover, as plain types and
 * functions: they hold no state and call no hook, so a Server Component can
 * use them too. Every formatter takes the locale and the time zone, so the
 * server and the browser write the same text for the same moment.
 */

/** Something a moment can be written as: a Date, a timestamp or an ISO string. */
export type EventMoment = Date | string | number;

/** Whether the event is on, still a maybe, or called off. */
export type EventStatus = "confirmed" | "tentative" | "cancelled";

/** One person who is invited. */
export interface EventPerson {
  /** A stable identity from your own data. */
  id: string;
  /** Their name. */
  name: string;
  /** A picture. Initials stand in while it loads, or when there is none. */
  image?: string;
}

/** The event a panel describes. */
export interface EventInfo {
  /** What it is: "Design review". */
  title: string;
  /** When it starts. For an all-day event, midnight of its first day in `timeZone`. */
  start: EventMoment;
  /** When it ends. Leave it out for an event that is only a moment. For an all-day event, midnight after its last day. */
  end?: EventMoment;
  /** An all-day event: the panel shows the date or dates and "All day", no clock times. */
  allDay?: boolean;
  /** The IANA time zone the event was made in: "Europe/Amsterdam". The times are shown in it first. Default "UTC". */
  timeZone?: string;
  /** Where it takes place: an address, a room. */
  location?: string;
  /** Where to join online. An http or https address becomes a link; anything else is shown as text. */
  link?: string;
  /** Who is invited. Shown as a stack of avatars with the count. */
  attendees?: readonly EventPerson[];
  /** More about it. Cut to four lines, with a button to read the rest. */
  description?: string;
  /** Default "confirmed". A cancelled event has its title struck through and says so. */
  status?: EventStatus;
}

/** The words the panel says, for translation. `{when}`, `{count}` and `{end}` are filled in. */
export interface EventDetailsLabels {
  /** The close button's name. Default "Close". */
  close?: string;
  /** Said instead of a clock time for an all-day event. Default "All day". */
  allDay?: string;
  /** The end of an event that runs over midnight: "to Sat 31 Oct, 02:00". Default "to {end}". */
  until?: string;
  /** In front of the time in the reader's own zone. Default "Your time". */
  yourTime?: string;
  /** The word for a cancelled event. Default "Cancelled". */
  cancelled?: string;
  /** The word for an event that is not confirmed yet. Default "Tentative". */
  tentative?: string;
  /** The word for an event that is on right now. Default "Happening now". */
  now?: string;
  /** The word for an event that is over. Default "Ended {when}", as in "Ended 3 days ago". */
  ended?: string;
  /** The link to join online. Default "Join video call". */
  join?: string;
  /** Said to screen readers after a link that opens a new tab. Default "(opens in a new tab)". */
  newTab?: string;
  /** The number of people when it is one. Default "{count} person". */
  attendeesOne?: string;
  /** The number of people otherwise. Default "{count} people". */
  attendeesOther?: string;
  /** The end of the names, for those not named. Default "{count} more". */
  andMore?: string;
  /** The name of the list of people for screen readers. Default "Attendees". */
  attendees?: string;
  /** The button that shows all of a long description. Default "Show more". */
  showMore?: string;
  /** The button that cuts it again. Default "Show less". */
  showLess?: string;
}

export const DEFAULT_LABELS = {
  close: "Close",
  allDay: "All day",
  until: "to {end}",
  yourTime: "Your time",
  cancelled: "Cancelled",
  tentative: "Tentative",
  now: "Happening now",
  ended: "Ended {when}",
  join: "Join video call",
  newTab: "(opens in a new tab)",
  attendeesOne: "{count} person",
  attendeesOther: "{count} people",
  andMore: "{count} more",
  attendees: "Attendees",
  showMore: "Show more",
  showLess: "Show less",
} satisfies Required<EventDetailsLabels>;

/** Puts values into a template: `fill("Ended {when}", { when: "yesterday" })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? (values[key] ?? match) : match));
}

/** A moment as milliseconds since 1970, or null when it is missing or not a date. */
export function momentOf(value: EventMoment | null | undefined): number | null {
  if (value === null || value === undefined) return null;
  const at = value instanceof Date ? value.getTime() : typeof value === "number" ? value : new Date(value).getTime();
  return Number.isNaN(at) ? null : at;
}

// Intl writes some spaces as narrow or thin no-break spaces, and the version of its data decides which: a plain space looks the same and every engine agrees on it.
const ODD_SPACES = new RegExp(`[${String.fromCharCode(0x00a0, 0x2009, 0x202f)}]`, "g");

/** A date or a time in a zone. An unknown locale or zone falls back to US English and UTC instead of taking the page down. */
function format(at: number, locale: string, timeZone: string, options: Intl.DateTimeFormatOptions): string {
  let text: string;
  try {
    text = new Intl.DateTimeFormat(locale, { ...options, timeZone }).format(at);
  } catch {
    text = new Intl.DateTimeFormat("en-US", { ...options, timeZone: "UTC" }).format(at);
  }
  return text.replace(ODD_SPACES, " ");
}

/** The way times are written: "09:00" on a 24-hour clock, so a column of them lines up, and "9:00 AM" on a 12-hour one. */
function clockOptions(locale: string): Intl.DateTimeFormatOptions {
  try {
    const cycle = new Intl.DateTimeFormat(locale, { hour: "numeric" }).resolvedOptions().hourCycle;
    return { hour: cycle === "h23" || cycle === "h24" ? "2-digit" : "numeric", minute: "2-digit" };
  } catch {
    return { hour: "numeric", minute: "2-digit" };
  }
}

const FULL_DAY: Intl.DateTimeFormatOptions = { weekday: "long", day: "numeric", month: "long" };
const SHORT_DAY: Intl.DateTimeFormatOptions = { weekday: "short", day: "numeric", month: "short" };

/** The calendar day a moment falls on in a zone, as "2026-10-27". The format of en-CA is the one that sorts. */
export function dayKey(at: number, timeZone: string): string {
  return format(at, "en-CA", timeZone, { year: "numeric", month: "2-digit", day: "2-digit" });
}

/** When an event happens, written for one zone. */
export interface When {
  /** The day: "Tuesday, 27 October". For an event over midnight it carries the start: "Fri 30 Oct, 22:00". */
  day: string;
  /** The short form of the day, for comparing and for a second line: "Tue 27 Oct". */
  shortDay: string;
  /** The clock: "10:00 – 11:30". For an event over midnight the end: "to Sat 31 Oct, 02:00". */
  time: string;
  /** Whether the event runs over midnight in this zone. */
  overnight: boolean;
}

export function whenOf(startAt: number, endAt: number | null, allDay: boolean, timeZone: string, locale: string, words: { allDay: string; until: string }): When {
  const clock = clockOptions(locale);
  const startDay = format(startAt, locale, timeZone, FULL_DAY);
  const startShort = format(startAt, locale, timeZone, SHORT_DAY);

  if (allDay) {
    // An all-day event ends at midnight after its last day, so its last day is the millisecond before.
    const last = endAt !== null && endAt > startAt ? endAt - 1 : startAt;
    const overnight = dayKey(last, timeZone) !== dayKey(startAt, timeZone);
    const lastShort = format(last, locale, timeZone, SHORT_DAY);
    return { day: overnight ? `${startShort} – ${lastShort}` : startDay, shortDay: overnight ? `${startShort} – ${lastShort}` : startShort, time: words.allDay, overnight };
  }

  const begin = format(startAt, locale, timeZone, clock);
  if (endAt === null || endAt <= startAt) return { day: startDay, shortDay: startShort, time: begin, overnight: false };
  const finish = format(endAt, locale, timeZone, clock);
  if (dayKey(endAt, timeZone) === dayKey(startAt, timeZone)) return { day: startDay, shortDay: startShort, time: `${begin} – ${finish}`, overnight: false };
  const endShort = format(endAt, locale, timeZone, SHORT_DAY);
  return { day: `${startShort}, ${begin}`, shortDay: startShort, time: fill(words.until, { end: `${endShort}, ${finish}` }), overnight: true };
}

/**
 * The event in the reader's zone, or null when the clock reads the same there. When only the day differs it carries the
 * day: "Wed 28 Oct, 00:30 – 02:00"; otherwise just the clock.
 */
export function viewerLine(own: When, theirs: When): string | null {
  if (own.day === theirs.day && own.time === theirs.time) return null;
  if (theirs.overnight) return `${theirs.day} ${theirs.time}`;
  return theirs.shortDay === own.shortDay ? theirs.time : `${theirs.shortDay}, ${theirs.time}`;
}

/** A zone for a caption: the city and the offset, "Amsterdam (GMT+1)". UTC is just UTC. */
export function zoneText(at: number, timeZone: string, locale: string): string {
  if (timeZone === "UTC") return "UTC";
  const city = (timeZone.split("/").pop() ?? timeZone).replace(/_/g, " ");
  let offset = "";
  for (const style of ["shortOffset", "short"] as const) {
    try {
      offset = new Intl.DateTimeFormat(locale, { timeZone, timeZoneName: style }).formatToParts(at).find((part) => part.type === "timeZoneName")?.value ?? "";
      if (offset) break;
    } catch {
      // An older engine does not know shortOffset, and a typo in a zone is not worth a crash: the city alone will do.
    }
  }
  // "GMT+0" is how some engines write no offset at all; "GMT" is how people do.
  offset = offset.replace(/^(GMT|UTC)[+-]0(?::00)?$/, "$1");
  return offset && offset !== city ? `${city} (${offset})` : city;
}

/** Whether the event is still to come, on right now, or over. An event with no end is over the moment it starts. */
export type EventPhase = "upcoming" | "live" | "past";

export function phaseOf(startAt: number, endAt: number | null, now: number): EventPhase {
  const end = endAt !== null && endAt > startAt ? endAt : startAt;
  if (now < startAt) return "upcoming";
  return now < end ? "live" : "past";
}

/** How long ago something was, in words: "5 minutes ago", "yesterday", "3 weeks ago". */
export function agoText(now: number, then: number, locale: string): string {
  const minutes = Math.max(1, Math.round((now - then) / 60_000));
  let value = -minutes;
  let unit: Intl.RelativeTimeFormatUnit = "minute";
  if (minutes >= 60 * 24 * 60) [value, unit] = [-Math.round(minutes / (60 * 24 * 30)), "month"];
  else if (minutes >= 60 * 24 * 14) [value, unit] = [-Math.round(minutes / (60 * 24 * 7)), "week"];
  else if (minutes >= 60 * 24) [value, unit] = [-Math.round(minutes / (60 * 24)), "day"];
  else if (minutes >= 60) [value, unit] = [-Math.round(minutes / 60), "hour"];
  let text: string;
  try {
    text = new Intl.RelativeTimeFormat(locale, { numeric: "auto" }).format(value, unit);
  } catch {
    text = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" }).format(value, unit);
  }
  return text.replace(ODD_SPACES, " ");
}

/** An address that is safe to link to: http or https only, so a `javascript:` address from user data never becomes a link. */
export function safeLink(link: string): { href: string; text: string } | null {
  try {
    const url = new URL(link);
    if (url.protocol !== "https:" && url.protocol !== "http:") return null;
    return { href: url.href, text: `${url.host}${url.pathname === "/" ? "" : url.pathname}` };
  } catch {
    return null;
  }
}

/** A number the way the locale writes it. */
export function numberText(value: number, locale: string): string {
  try {
    return new Intl.NumberFormat(locale).format(value);
  } catch {
    return new Intl.NumberFormat("en-US").format(value);
  }
}

/** The people in a line: all of them up to three, then two and a count. "Mara Visser, Tom Jansen and 4 more". */
export function peopleLine(names: readonly string[], locale: string, andMore: string): string {
  const parts = names.length <= 3 ? [...names] : [...names.slice(0, 2), fill(andMore, { count: numberText(names.length - 2, locale) })];
  try {
    return new Intl.ListFormat(locale, { style: "long", type: "conjunction" }).format(parts);
  } catch {
    return parts.join(", ");
  }
}
